""" split a 1D list atoms into n nearly-even-sized chunks.
    """
def distribute_atoms(atoms: Any, n: Any) -> object {
    (k, m) = divmod(len(atoms), n);
    return [
        atoms[((i * k) + min(i, m)):(((i + 1) * k) + min((i + 1), m))] for i in range(n)
    ];
}

"""
    Simplifies a long names of thread (for Zafira UI),
    e.g. MainThread -> MT, ThreadPoolExecutor -> TPE, etc.
    :param thread_name: thread name from Log Record object
    :return: simplified thread name
    """
def normalized_thread_name(thread_name: Any) -> object {
    normalized = '';
    for symb in thread_name {
        if symb.isupper() {
            normalized += symb;
        }
    }
    return normalized;
}

"""
    Complete the solution so that it strips all text that follows any of a set of comment markers passed in.
    Any whitespace at the end of the line should also be stripped out.
    :param string: a string input.
    :param markers: list of characters.
    :return: a new string with whitespace and comment markers removed.
    """
def strip_comments(string: Any, markers: Any) -> object {
    parts = string.split("\n");
    for v in markers {
        parts = [x.split(v)[0].rstrip() for x in parts];
    }
    return "\n".join(parts);
}

"""Joins matchers of lists correctly."""
def _join_matchers(matcher: Any, *matchers: Any) -> object {
    output = {k: [e for e in v] for (k, v) in matcher.items()};
    for matcher_to_join in matchers {
        has_default = False;
        for (key, value) in matcher_to_join.items() {
            if (key == "default") {
                has_default = True;
            }
            if (key in output) {
                output[key].extend(value);
            } else {
                output[key] = value;
                if (("default" in output) and (key != "default")) {
                    value.extend(output["default"]);
                }
            }
        }
        if has_default {
            for key in output.keys() {
                if (key not in matcher_to_join) {
                    output[key].extend(matcher_to_join["default"]);
                }
            }
        }
    }
    return output;
}

