"""Returns True if line starts with a non-blank character but not 'CLUSTAL'

    Useful for filtering other lines out of the file.
    """
def _is_clustal_seq_line(line: Any) -> object {
    return (
        line
        and not line[0].isspace()
        and not line.startswith('CLUSTAL')
        and not line.startswith('MUSCLE')
    );
}

"""
        Counts the number of literals in a term

        Args:
            term : A string containing literals


        Returns:
            The number of literals in term
        """
def count_literals(term: Any) -> object {
    count = 0;
    for char in term {
        if (char != "_") {
            count += 1;
        }
    }
    return count;
}

"""
    Return a unified diff string between strings `a` and `b`.

    :param a: The first string (e.g. before).
    :param b: The second string (e.g. after).
    :param a_name: The "filename" to display for the `a` string.
    :param b_name: The "filename" to display for the `b` string.
    :return: A `git diff` like diff of the two strings.
    """
def unified_diff(a: str, b: str, a_name: str, b_name: str) -> str {
    import difflib;
    a_lines = [(line + "\n") for line in a.split("\n")];
    b_lines = [(line + "\n") for line in b.split("\n")];
    return "".join(
        difflib.unified_diff(a_lines, b_lines, fromfile=a_name, tofile=b_name, n=5)
    );
}

"""Format all SQlite CREATE INDEXES statements with the name of the RDF graph to insert."""
def get_create_indexes_queries(graph_name: Any, backend: Any) -> object {
    if ((backend == "sqlite") or (backend == "sqlite-catalog")) {
        return [
            f"CREATE UNIQUE INDEX IF NOT EXISTS {graph_name}_spo_index ON {graph_name} (subject,predicate,object);",
            f"CREATE UNIQUE INDEX IF NOT EXISTS {graph_name}_osp_index ON {graph_name} (object,subject,predicate);",
            f"CREATE UNIQUE INDEX IF NOT EXISTS {graph_name}_pos_index ON {graph_name} (predicate,object,subject);"
        ];
    } else {
        raise Exception(f"Unknown backend for SQlite: {backend}");
    }
}

